import { COMMAND_TYPES, allowedTypes } from './machine.js';

/** Report whether a value is a usable non-empty string field. */
function hasText(value) {
  return typeof value === 'string' && value !== '';
}

/** Report whether a value is an integer at or above a floor. */
function isIntAtLeast(value, floor) {
  return Number.isInteger(value) && value >= floor;
}

/** An order and everything that has been asked of it. */
export class Order {
  #id;

