      if (!hasText(command.sku)) return { code: 'MISSING_FIELD', message: 'sku must be a non-empty string' };
    }
    if (type === 'ship') {
      if (!hasText(command.carrier)) return { code: 'MISSING_FIELD', message: 'carrier must be a non-empty string' };
      if (!hasText(command.tracking)) return { code: 'MISSING_FIELD', message: 'tracking must be a non-empty string' };
    }
    if (type === 'cancel') {
      if (!hasText(command.reason)) return { code: 'MISSING_FIELD', message: 'reason must be a non-empty string' };
    }
    if (type === 'addItem') {
      if (!isIntAtLeast(command.qty, 1)) return { code: 'BAD_AMOUNT', message: 'qty must be an integer of at least 1' };
      if (!isIntAtLeast(command.unitPriceCents, 0)) {
        return { code: 'BAD_AMOUNT', message: 'unitPriceCents must be a non-negative integer' };
      }
    }
    if (type === 'pay' && !isIntAtLeast(command.amountCents, 0)) {
      return { code: 'BAD_AMOUNT', message: 'amountCents must be a non-negative integer' };
    }
    if (type === 'refund' && !isIntAtLeast(command.amountCents, 1)) {
      return { code: 'BAD_AMOUNT', message: 'amountCents must be an integer of at least 1' };
    }

