   * Record a rejected command.
   *
   * @param {object} command Command that failed.
   * @param {number} at Timestamp to stamp on the entry.
   * @param {string} code Failure code.
   * @param {string} message Human explanation.
   * @returns {object} The rejection result.
   */
  #reject(command, at, code, message) {
    return this.#record(command, at, this.#state, false, code, message);
  }

  /**
   * Append an audit entry and remember the result for this command id.
   *
   * @param {object} command Command that ran.
   * @param {number} at Timestamp to stamp on the entry.
   * @param {string} from State before the command.
   * @param {boolean} ok Whether the command succeeded.
   * @param {string|null} code Failure code, when rejected.
   * @param {string|null} message Human explanation, when rejected.
   * @returns {object} The result handed to the caller.
   */
  #record(command, at, from, ok, code, message) {
    const seq = this.#audit.length + 1;
    const entry = { seq, commandId: command.commandId, type: command.type, at, from, to: this.#state, ok };
    if (!ok) entry.code = code;
    this.#audit.push(entry);
    const result = ok
